'use strict';
Object.assign(iconPaths,{pin:'M9 3h6l-1 6 4 4v2H6v-2l4-4-1-6 M12 15v6',plus:'M12 5v14 M5 12h14',check:'m5 12 4 4L19 6',leaf:'M20 4C5 2 2 10 6 16s15 3 14-12Z M6 18 16 8'});
const APP_VERSION='1.4.1';
const RELEASES=[{version:APP_VERSION,title:'Checklist gọn & thư viện tài nguyên',text:'Checklist một dòng, tổng kết email có biểu đồ % và tiến độ từng dự án, xem trước/In/Lưu PDF, album Tài nguyên riêng tư quản lý tệp.'},{version:'1.4.0',title:'Bức tranh công việc & tổng kết tuần',text:'Biểu đồ tương tác bốn màu, nhắc hạn trước 3 ngày, email tổng kết Chủ nhật trong Settings, bảng icon và bánh xe HEX/RGB. Lưu trữ dự án đang làm dở.'},{version:'1.3.8',title:'Lời chào mỗi ngày tinh gọn hơn',text:'Lược bỏ phần hiển thị bản dịch và bản tiếng Anh, cải thiện kiểu chữ, căn dòng và nút đóng.'},{version:'1.3.7',title:'Ma trận ưu tiên bốn màu',text:'Cập nhật bốn nhãn theo mức độ quan trọng và khẩn cấp: tím, xanh lá, hồng và cam.'},{version:'1.3.6',title:'Toàn cảnh & công việc trong một màn hình',text:'Thống kê quá hạn, tổng quan đầu trang mobile, chỉnh task trực tiếp, ma trận bốn màu, tùy chọn Kanban và tiến độ Timeline/Calendar. Hướng dẫn đầy đủ.'},{version:'1.3.4',title:'Thông báo đã xem & chuyển bước công việc',text:'Nút Đã xem tất cả đưa bộ đếm về bình thường. Chuyển task sang cột kế tiếp ngay trên thẻ.'},{version:'1.3.3',title:'Ghi chú trực tiếp & lời chào mỗi ngày',text:'Viết ghi chú, thêm liên kết và tải tệp trong cùng khung. Lời chào hằng ngày có họa tiết thiên nhiên.'}];
let latestVersion=APP_VERSION;
function localRead(k){try{return localStorage.getItem(k);}catch{return null;}}
function localWrite(k,v){try{localStorage.setItem(k,v);}catch{}}
function releaseKey(){return 'zen-release-seen:'+currentUser?.id;}
function releaseUnread(){return !!currentUser&&localRead(releaseKey())!==latestVersion;}
const oldBellRefresh=refreshBell;refreshBell=function(){oldBellRefresh();if(releaseUnread()){const count=taskNotices().length+fileAlerts.length+1;bell.innerHTML=svgIcon('bell')+'<span class="notification-count">'+(count>99?'99+':count)+'</span>';bell.setAttribute('aria-label','Thông báo · '+count+' mục, có phiên bản mới');}};
const oldBellClick=bell.onclick;bell.onclick=()=>{oldBellClick();const list=$('#editor-body .notice-list');list.insertAdjacentHTML('afterbegin',`<article class="notice-item release-notice"><strong>${releaseUnread()?'Mới · ':''}Phiên bản ${esc(latestVersion)}</strong><span>${latestVersion===APP_VERSION?esc(RELEASES[0].text):'Có bản cập nhật mới. Tải lại trang để nhận tính năng mới nhất.'}</span><button class="btn" type="button" id="release-read">${svgIcon('check')}Đã đọc</button>${latestVersion!==APP_VERSION?'<button class="btn" id="release-reload" type="button">Tải lại trang</button>':''}</article>`);$('#release-read').onclick=()=>{localWrite(releaseKey(),latestVersion);refreshBell();$('#release-read').textContent='Đã đọc';};if($('#release-reload'))$('#release-reload').onclick=()=>location.reload();};
versions=()=>heading('NHẬT KÝ PHÁT TRIỂN','Phiên bản '+APP_VERSION,'Những thay đổi mới nhất')+'<section class="panel release">'+RELEASES.map(r=>`<div class="timeline-item"><h4>v${r.version} · ${esc(r.title)}</h4><p>${esc(r.text)}</p></div>`).join('')+'</section>';
async function checkRelease(){if(!currentUser||document.hidden||!navigator.onLine)return;try{const r=await fetch('/health',{cache:'no-store'});if(r.ok){const body=await r.json();if(/^\d+\.\d+\.\d+$/.test(body.version)){latestVersion=body.version;refreshBell();}}}catch{}}
let wisdomCache=null,welcomeLoading=false,welcomeSession=new Set();
function welcomeDay(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function wisdomIndex(day,count){return Math.floor((Date.parse(day+'T00:00:00Z')-Date.parse('2026-10-24T00:00:00Z'))/86400000+count*1000)%count;}
async function dailyWelcome(){if(!currentUser||document.hidden||welcomeLoading||$('#editor').open||document.querySelector('.welcome-dialog'))return;const owner=currentUser.id,day=welcomeDay(),key='zen-welcome:'+owner+':'+day;if(localRead(key)||welcomeSession.has(key))return;welcomeLoading=true;try{if(!wisdomCache){const response=await fetch('/wisdom.json');if(!response.ok)throw Error('wisdom');wisdomCache=await response.json();}if(!currentUser||currentUser.id!==owner||$('#editor').open)return;const q=wisdomCache[wisdomIndex(day,wisdomCache.length)],d=document.createElement('dialog');d.className='welcome-dialog';d.setAttribute('aria-labelledby','welcome-title');d.innerHTML=`<button type="button" class="welcome-close" aria-label="Đóng lời chào" title="Đóng">×</button><div class="welcome-nature" aria-hidden="true">${svgIcon('leaf')}${svgIcon('leaf')}${svgIcon('leaf')}</div><div class="completion-fireworks" aria-hidden="true"></div><div class="welcome-content"><div class="welcome-lotus" aria-hidden="true">❀</div><p class="eyebrow">MỘT NGÀY MỚI · MỘT ĐIỀU ĐỂ CHIÊM NGHIỆM</p><h2 id="welcome-title">Chào mừng bạn trở lại</h2><blockquote lang="vi">${esc(q.vi)}</blockquote><p class="wisdom-author">— ${esc(q.author)}</p><a href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">${esc(q.source)} ↗</a>${q.contextUrl?'<a href="'+esc(q.contextUrl)+'" target="_blank" rel="noopener noreferrer">Giải nghĩa ẩn dụ trong kinh ↗</a>':''}<p class="welcome-bottom">Hít thở chậm. Bắt đầu bằng một việc nhỏ.</p></div>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.querySelector('.welcome-close').onclick=()=>d.close();d.showModal();welcomeSession.add(key);localWrite(key,'seen');if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const layer=d.querySelector('.completion-fireworks');for(let burst=0;burst<3;burst++)for(let i=0;i<16;i++){const angle=i/16*Math.PI*2,p=document.createElement('i');p.className='completion-particle';p.style.cssText=`left:${20+burst*30}%;top:${25+burst*10}%;--dx:${Math.cos(angle)*100}px;--dy:${Math.sin(angle)*100}px;--delay:${burst*180}ms;--particle:${['#86aa8c','#d6ac68','#c39cc6'][burst]}`;layer.append(p);}setTimeout(()=>layer.remove(),2500);}}catch{}finally{welcomeLoading=false;}}
const beforeWelcomeRender=render;render=function(){beforeWelcomeRender();setTimeout(dailyWelcome,700);};
setInterval(checkRelease,300000);setInterval(dailyWelcome,60000);window.addEventListener('focus',()=>{checkRelease();dailyWelcome();});setTimeout(dailyWelcome,1000);refreshBell();
function noticeSignature(t){return [t.id,t.notice,t.due||'',t.title,t.important].join('|');}
function seenNotices(){try{return JSON.parse(localRead('zen-notices:'+currentUser?.id)||'[]');}catch{return [];}}
function markNoticesRead(){localWrite('zen-notices:'+currentUser?.id,JSON.stringify(taskNotices().map(noticeSignature)));fileAlerts=[];localWrite(releaseKey(),latestVersion);refreshBell();}
refreshBell=function(){const seen=new Set(seenNotices()),count=taskNotices().filter(t=>!seen.has(noticeSignature(t))).length+fileAlerts.length+(releaseUnread()?1:0);bell.innerHTML=svgIcon('bell')+(count?'<span class="notification-count">'+(count>99?'99+':count)+'</span>':'');bell.setAttribute('aria-label','Thông báo · '+count+' chưa xem');};
const beforeReadBell=bell.onclick;bell.onclick=()=>{beforeReadBell();const b=$('#clear-file-alerts');b.textContent='Đã xem tất cả';b.onclick=()=>{markNoticesRead();$('#editor').close();};};
const beforeNextCard=taskCard;taskCard=function(t,p){const html=beforeNextCard(t,p),next=p.columns[p.columns.indexOf(t.col)+1];return next?html.replace('</article>',`<button type="button" class="btn task-next" data-next-task="${esc(t.id)}" data-next-project="${esc(p.id)}">${svgIcon('check')}Chuyển sang ${esc(next)} →</button></article>`):html;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-next-task]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const p=project(b.dataset.nextProject),t=p?.tasks.find(t=>t.id===b.dataset.nextTask);if(!t)return;const next=p.columns[p.columns.indexOf(t.col)+1];if(!next)return;t.col=next;if(next==='Done'){t.checks.forEach(c=>c.done=true);celebrateCompletion('task');}save();render();},true);
refreshBell();
